let array = $('Edit Fields4').first().json.turnos;
let data = $('Code14').first().json;
array.push(data);

return $input.all()

const datos = $input.all();
const entrada = $('When Executed by Another Workflow').first().json;
const fechaBuscada = entrada.fecha;
const horaBuscada = entrada.hora;

if (!fechaBuscada || !horaBuscada) {
  return [{
    json: {
      encontrado: false,
      mensaje: "Faltan parámetros: 'date' y/o 'hour_code' no fueron proporcionados."
    }
  }];
}

const agregarDosP = (hora) => {
  const limpia = hora.replace(':', '');
  return limpia.slice(0, 2) + ':' + limpia.slice(2);
};

const horaBuscadaNorm = agregarDosP(horaBuscada);

const datosValidos = datos.filter(item =>
  item?.json &&
  item.json.date &&
  item.json.hour &&
  item.json.hour.name &&
  item.json.workshop_appointment_guid === null 
  // &&  item.json.user?.name === "RH Recepcion.Taller"
);

const turnoEncontrado = datosValidos.find(item =>
  item.json.date === fechaBuscada &&
  item.json.hour.name === horaBuscadaNorm
);

if (!turnoEncontrado) {
  return [{
    json: {
      encontrado: false,
      mensaje: `No hay disponibilidad para el ${fechaBuscada} a las ${horaBuscadaNorm}.`
    }
  }];
}

return [{
  json: {
    encontrado: true,
    date: turnoEncontrado.json.date,
    hour_code: turnoEncontrado.json.hour.code,
    hour_name: turnoEncontrado.json.hour.name,
    user_id: turnoEncontrado.json.user.id,
    user_name: turnoEncontrado.json.user.name
  }
}];

